begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(36);
insert into auth.users(id,email) values('99300000-0000-4000-8000-000000000001','tax-preparer@example.test'),('99300000-0000-4000-8000-000000000002','tax-reviewer@example.test');
insert into public.app_users(id,email,full_name) values('99300000-0000-4000-8000-000000000001','tax-preparer@example.test','Tax preparer'),('99300000-0000-4000-8000-000000000002','tax-reviewer@example.test','Tax reviewer');
insert into public.orgs(id,name,slug) values('99300000-0000-4000-8000-000000000003','Tax workpaper acceptance','tax-workpaper-acceptance');
insert into public.roles(id,key,label,scope) values('99300000-0000-4000-8000-000000000004','tax_workpaper_acceptance','Tax acceptance','org');
insert into public.memberships(org_id,user_id,role_id) values('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','99300000-0000-4000-8000-000000000004'),('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000002','99300000-0000-4000-8000-000000000004');
create function pg_temp.tax_base() returns jsonb language sql as $$select jsonb_build_object('basis','cash','version',1,'start_date','2026-01-01','end_date','2026-12-31','net_income_cents',0,'source_revision',public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'))$$;
create function pg_temp.tax_lines(amount bigint default 500) returns jsonb language sql as $$ select jsonb_build_array(jsonb_build_object('id','99300000-0000-4000-8000-000000000005','kind','permanent','amount_cents',amount,'description','Reviewed permanent difference','evidence_reference','Tax workpaper acceptance evidence','evidence_file_id',null,'project_id',null)) $$;
create function pg_temp.tax_prepare(key text, supersedes uuid default null, lines jsonb default pg_temp.tax_lines()) returns uuid language sql as $$select public.prepare_books_tax_workpaper('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','2026-01-01','2026-12-31',repeat('a',64),pg_temp.tax_base(),lines,key,supersedes)$$;
create temporary table tax_ids(name text primary key,id uuid);
select ok(not has_function_privilege('authenticated','public.prepare_books_tax_workpaper(uuid,uuid,date,date,text,jsonb,jsonb,text,uuid,text)','execute') and not has_function_privilege('anon','public.review_books_tax_workpaper(uuid,uuid,uuid,text,text)','execute'),'browser roles cannot prepare or review workpapers');
select ok((select relrowsecurity from pg_class where oid='public.books_tax_adjustment_workpapers'::regclass) and not has_table_privilege('authenticated','public.books_tax_adjustment_workpapers','select') and not has_table_privilege('anon','public.books_tax_adjustment_workpapers','insert'),'RLS and revoked browser table access protect workpapers');
select lives_ok($$insert into tax_ids values('original',pg_temp.tax_prepare('tax-original-retry-key'))$$,'prepare native scoped draft');
select is(pg_temp.tax_prepare('tax-original-retry-key'),(select id from tax_ids where name='original'),'identical preparation retry returns same draft');
select throws_like($$select pg_temp.tax_prepare('tax-original-retry-key',null,pg_temp.tax_lines(501))$$,'%retry key has different evidence%','retry key cannot overwrite evidence');
select throws_like($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from tax_ids where name='original'),'99300000-0000-4000-8000-000000000001',repeat('a',64),'Reviewed source and adjustment evidence')$$,'%different active organization reviewer%','preparer cannot self-review');
select throws_like($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from tax_ids where name='original'),'99300000-0000-4000-8000-000000000002',repeat('b',64),'Reviewed source and adjustment evidence')$$,'%Cash books changed%','changed basis digest blocks review');
select throws_like($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from tax_ids where name='original'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'ok')$$,'%Substantive tax review notes%','approval requires substantive review notes');
select lives_ok($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from tax_ids where name='original'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'Reviewed source and adjustment evidence')$$,'separate reviewer approves');
select is(public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from tax_ids where name='original'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'Reviewed source and adjustment evidence'),(select id from tax_ids where name='original'),'approval retry is idempotent');
select throws_like($$update public.books_tax_adjustment_workpapers set lines=pg_temp.tax_lines(999) where id=(select id from tax_ids where name='original')$$,'%evidence is immutable%','approved adjustments cannot be rewritten');
select throws_like($$delete from public.books_tax_adjustment_workpapers where id=(select id from tax_ids where name='original')$$,'%cannot be deleted%','tax history cannot be deleted');
select lives_ok($$insert into tax_ids values('overlap',pg_temp.tax_prepare('tax-overlap-retry-key'))$$,'another draft may be prepared for review');
select throws_like($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from tax_ids where name='overlap'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'Reviewed source and adjustment evidence')$$,'%one workpaper may be approved%','only one workpaper is counted for an exact reporting period');
select lives_ok($$insert into tax_ids values('replacement',pg_temp.tax_prepare('tax-replacement-retry-key',(select id from tax_ids where name='original'),pg_temp.tax_lines(700)))$$,'replacement preserves original reference');
select lives_ok($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from tax_ids where name='replacement'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'Reviewed replacement and original evidence')$$,'replacement approval atomically supersedes original');
select is((select status from public.books_tax_adjustment_workpapers where id=(select id from tax_ids where name='original')),'superseded','original retained as superseded evidence');
select is((select status from public.books_tax_adjustment_workpapers where id=(select id from tax_ids where name='replacement')),'approved','only replacement remains approved');
select is((select (lines->0->>'amount_cents')::bigint from public.books_tax_adjustment_workpapers where id=(select id from tax_ids where name='original')),500::bigint,'original signed adjustment retained exactly');
select is((select count(*) from public.journal_entries where org_id='99300000-0000-4000-8000-000000000003'),0::bigint,'tax adjustments do not post accrual journals');
select is(jsonb_array_length(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003')->'tables'->'books_tax_adjustment_workpapers'),3,'all tax workpaper versions included in atomic export');
select throws_like($$select pg_temp.tax_prepare('tax-foreign-document-key',null,jsonb_set(pg_temp.tax_lines(),'{0,evidence_file_id}','"99300000-0000-4000-8000-000000000099"'))$$,'%evidence file is outside organization%','foreign or missing evidence file rejected');
select throws_like($$select public.prepare_books_tax_workpaper('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','2026-01-01','2026-12-31',repeat('a',64),pg_temp.tax_base()-'basis',pg_temp.tax_lines(),'tax-missing-basis-key',null)$$,'%exact dated cash basis%','missing basis fields cannot pass nullable CHECK expressions');
select throws_like($$select pg_temp.tax_prepare('tax-unsafe-integer-key',null,pg_temp.tax_lines(9007199254740992))$$,'%signed exact cents%','unsafe cents rejected');
select throws_like($$select pg_temp.tax_prepare('tax-string-integer-key',null,jsonb_set(pg_temp.tax_lines(),'{0,amount_cents}','"500"'))$$,'%signed exact cents%','numeric strings are not accepted as exact signed JSON cents');
select throws_like($$select public.prepare_books_tax_workpaper('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000099','2026-01-01','2026-12-31',repeat('a',64),pg_temp.tax_base(),pg_temp.tax_lines(),'tax-missing-actor-key',null)$$,'%active organization member%','actor must belong to organization');
select is(public.books_tax_source_revision(jsonb_set(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'{tables,journal_entries}','[{"id":"future","entry_date":"2027-01-01","status":"posted","fact_id":null}]'),'2026-12-31'),public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'),'future transactions do not invalidate prior-period review');
select isnt(public.books_tax_source_revision(jsonb_set(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'{tables,journal_entries}','[{"id":"late","entry_date":"2026-12-31","status":"posted","fact_id":null}]'),'2026-12-31'),public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'),'late posted history invalidates the source revision');
select is(public.capture_books_tax_workpaper_context('99300000-0000-4000-8000-000000000003','2026-12-31')->>'taxSourceRevision',public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'),'tax context carries one-statement source revision');
select isnt(public.books_tax_source_revision(jsonb_set(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'{tables,payments}','[{"id":"unposted","received_at":"2026-12-31T12:00:00Z","status":"completed"}]'),'2026-12-31'),public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'),'new completed payment without a journal invalidates review revision');
select is(public.books_tax_source_revision(jsonb_set(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'{tables,payments}','[{"id":"future","received_at":"2027-01-01T12:00:00Z","status":"completed"}]'),'2026-12-31'),public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'),'future-period completed payment does not invalidate prior review');
select throws_like($$update public.books_tax_adjustment_workpapers set status='approved',reviewed_by='99300000-0000-4000-8000-000000000002',reviewed_at=now(),review_notes=null where id=(select id from tax_ids where name='overlap')$$,'%substantive notes and a separate active reviewer%','NULL review notes cannot bypass approval guards');
select throws_like($$update public.books_tax_adjustment_workpapers set status='approved',reviewed_by='99300000-0000-4000-8000-000000000099',reviewed_at=now(),review_notes='Reviewed source and adjustments' where id=(select id from tax_ids where name='overlap')$$,'%substantive notes and a separate active reviewer%','direct privileged update still requires organization reviewer');
select throws_like($$select pg_temp.tax_prepare('tax-category-overflow-key',null,pg_temp.tax_lines(9007199254740991)||jsonb_build_array(jsonb_build_object('id','99300000-0000-4000-8000-000000000006','kind','permanent','amount_cents',1,'description','Reviewed permanent difference','evidence_reference','Tax workpaper evidence'),jsonb_build_object('id','99300000-0000-4000-8000-000000000007','kind','timing','amount_cents',-1,'description','Reviewed timing difference','evidence_reference','Tax workpaper evidence')))$$,'%category exceeds exact safe cents%','category overflow is rejected even when timing offsets make net total safe');
set local role service_role;
select lives_ok($$select public.prepare_books_tax_workpaper('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','2026-01-01','2026-12-31',repeat('a',64),pg_temp.tax_base(),pg_temp.tax_lines(800),'tax-service-role-retry-key',(select id from public.books_tax_adjustment_workpapers where org_id='99300000-0000-4000-8000-000000000003' and idempotency_key='tax-replacement-retry-key'))$$,'actual service role can prepare through invoker RPC and trigger grants');
select lives_ok($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from public.books_tax_adjustment_workpapers where org_id='99300000-0000-4000-8000-000000000003' and idempotency_key='tax-service-role-retry-key'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'Reviewed service role replacement evidence')$$,'actual service role can approve replacement through invoker RPC');
reset role;
select * from finish();
rollback;
